import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { ArrowDownRight, ArrowUpRight, BellRing, BookOpen, Bot, CalendarClock, CalendarDays, Camera, Check, ChevronRight, Cloud, Download, FileUp, Goal, LayoutDashboard, MoreHorizontal, Moon, PiggyBank, Plus, ReceiptText, RotateCcw, Send, Settings, ShieldCheck, SlidersHorizontal, Sun, Trash2, Users, WalletCards, X } from "lucide-react";
import { allocationSpent, categoryColors, createEmptyAppData, createFamilyCode, expenseCategories, formatDate, inPlanPeriod, isoToday, newId, normalizeAppData, parseRomanianAmount, pendingRecurringInPlan, planForecast, sourceBalance, type AppData, type BudgetAllocation, type Debt, type PaymentKind, type Receipt, type ReceiptLine, type SavingsGoal, type Transaction, type TransactionKind } from "@/lib/finance-data";
import { decryptFamilyData, encryptFamilyData, getRemotePackage, mergeFamilyData, saveRemotePackage } from "@/lib/github-sync";
import { compressReceiptImage, readReceiptLocally } from "@/lib/receipt-utils";
import { ReportsPanel } from "@/components/ReportsPanel";
import { RecurringPanel } from "@/components/RecurringPanel";

type MainView = "home" | "journal" | "plan" | "objectives" | "more";
type MoreView = "overview" | "debts" | "savings" | "receipts" | "recurring" | "reports" | "assistant" | "settings" | "sync" | "guide";
const STORE_KEY = "buget-familie:app-data-v6";
const LEGACY_KEY = "buget-familie:app-data-v3";
const fmt = new Intl.NumberFormat("ro-RO", { style: "currency", currency: "RON", maximumFractionDigits: 0 });
const fmtExact = new Intl.NumberFormat("ro-RO", { style: "currency", currency: "RON", minimumFractionDigits: 2, maximumFractionDigits: 2 });

const money = (value: number) => fmt.format(Number.isFinite(value) ? value : 0);
const dateText = (value: string, full = false) => formatDate(value, full ? { day: "2-digit", month: "long", year: "numeric" } : { day: "2-digit", month: "short" });
const sourceKindName: Record<PaymentKind, string> = { card: "Card", cash: "Cash", meal: "Bonuri de masă", transfer: "Transfer" };
type AdvisorAction = "plan" | "recurring" | "objectives" | "journal";
type AdvisorSignal = { id: string; tone: "good" | "watch" | "risk"; eyebrow: string; title: string; detail: string; action: AdvisorAction; actionLabel: string };

function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) {
  return <div className="bf-modal-backdrop" role="presentation" onMouseDown={onClose}><section className="bf-modal" role="dialog" aria-modal="true" aria-label={title} onMouseDown={(event) => event.stopPropagation()}><header><div><p className="bf-kicker">ÎNREGISTRARE RAPIDĂ</p><h2>{title}</h2></div><button className="bf-icon-button" aria-label="Închide" onClick={onClose}><X size={19} /></button></header>{children}</section></div>;
}

function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="bf-field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }

function TransactionForm({ data, initial, onSave, onClose }: { data: AppData; initial?: Transaction; onSave: (item: Transaction) => void; onClose: () => void }) {
  const [kind, setKind] = useState<TransactionKind>(initial?.kind || "expense");
  const [title, setTitle] = useState(initial?.title || "");
  const [amount, setAmount] = useState(initial ? String(initial.amount) : "");
  const [date, setDate] = useState(initial?.date || isoToday());
  const [memberId, setMemberId] = useState(initial?.memberId || data.settings.members.find((member) => member.name === initial?.person)?.id || data.settings.members[0]?.id || "");
  const [sourceId, setSourceId] = useState(initial?.sourceId || data.settings.paymentSources.find((source) => source.name === initial?.source)?.id || data.settings.paymentSources[0]?.id || "");
  const [category, setCategory] = useState(initial?.category || "Alimente");
  const [note, setNote] = useState(initial?.note || "");
  const [error, setError] = useState("");
  const save = () => {
    const numeric = parseRomanianAmount(amount);
    const source = data.settings.paymentSources.find((item) => item.id === sourceId);
    const member = data.settings.members.find((item) => item.id === memberId);
    if (!title.trim()) return setError("Scrie o denumire pentru mișcare.");
    if (!numeric || numeric <= 0) return setError("Introdu o sumă mai mare decât zero.");
    if (!source || !member || !date) return setError("Alege data, membrul și sursa de plată.");
    onSave({ id: initial?.id || newId("tx"), title: title.trim(), amount: numeric, kind, category: kind === "income" ? "Venit" : category, sourceId: source.id, source: source.name, memberId: member.id, person: member.name, date, note: note.trim() || undefined, createdAt: initial?.createdAt || new Date().toISOString(), receiptId: initial?.receiptId });
    onClose();
  };
  return <Modal title={initial ? "Corectează mișcarea" : "Adaugă mișcare"} onClose={onClose}><div className="bf-segment"><button className={kind === "expense" ? "active expense" : ""} onClick={() => setKind("expense")}>Cheltuială</button><button className={kind === "income" ? "active income" : ""} onClick={() => setKind("income")}>Venit</button></div><div className="bf-form-grid"><Field label="Denumire"><input autoFocus value={title} onChange={(event) => setTitle(event.target.value)} placeholder="ex. Cumpărături Lidl" /></Field><Field label="Sumă (lei)"><input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" placeholder="0,00" /></Field><Field label="Data"><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></Field><Field label="Cine a făcut mișcarea"><select value={memberId} onChange={(event) => setMemberId(event.target.value)}>{data.settings.members.map((member) => <option key={member.id} value={member.id}>{member.name}</option>)}</select></Field><Field label={kind === "income" ? "Încasat în" : "Plătit din"}><select value={sourceId} onChange={(event) => setSourceId(event.target.value)}>{data.settings.paymentSources.map((source) => <option key={source.id} value={source.id}>{source.name} · {money(sourceBalance(data, source.id))}</option>)}</select></Field>{kind === "expense" && <Field label="Categorie"><select value={category} onChange={(event) => setCategory(event.target.value)}>{[...expenseCategories, ...data.settings.customCategories].map((item) => <option key={item}>{item}</option>)}</select></Field>}</div><Field label="Notiță opțională"><textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="ex. apă, fructe, produse casă" /></Field>{error && <p className="bf-form-error" role="alert">{error}</p>}<button className="bf-primary full" onClick={save}><Check size={17} /> Salvează mișcarea</button></Modal>;
}

function GoalForm({ type, item, onSave, onClose }: { type: "debt" | "saving"; item?: Debt | SavingsGoal; onSave: (item: Debt | SavingsGoal) => void; onClose: () => void }) {
  const saving = type === "saving"; const old = item as SavingsGoal | undefined; const oldDebt = item as Debt | undefined;
  const [name, setName] = useState(item?.name || ""); const [one, setOne] = useState(item ? String(saving ? old?.current ?? 0 : oldDebt?.remaining ?? 0) : ""); const [two, setTwo] = useState(item ? String(saving ? old?.target ?? 0 : oldDebt?.monthly ?? 0) : ""); const [date, setDate] = useState(item?.dueDate || ""); const [error, setError] = useState("");
  const save = () => { const first = parseRomanianAmount(one); const second = parseRomanianAmount(two); if (!name.trim() || first < 0 || second < 0 || (saving && second <= 0)) return setError("Completează numele și sumele corecte."); if (saving) onSave({ id: item?.id || newId("goal"), name: name.trim(), current: first, target: second, due: date ? dateText(date, true) : "Fără termen", dueDate: date || undefined, tone: old?.tone || "honey" }); else onSave({ id: item?.id || newId("debt"), name: name.trim(), remaining: first, monthly: second, due: date ? dateText(date, true) : "Nespecificat", dueDate: date || undefined, tone: oldDebt?.tone || "coral" }); onClose(); };
  return <Modal title={saving ? "Obiectiv de economisire" : "Datorie sau rată"} onClose={onClose}><div className="bf-form-grid"><Field label={saving ? "Pentru ce economisiți?" : "Denumire"}><input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder={saving ? "ex. Fond de siguranță" : "ex. Credit bancar"} /></Field><Field label={saving ? "Strâns până acum (lei)" : "Sold rămas (lei)"}><input value={one} onChange={(event) => setOne(event.target.value)} inputMode="decimal" /></Field><Field label={saving ? "Țintă (lei)" : "Rată lunară (lei)"}><input value={two} onChange={(event) => setTwo(event.target.value)} inputMode="decimal" /></Field><Field label={saving ? "Data țintă" : "Scadență"}><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></Field></div>{error && <p className="bf-form-error" role="alert">{error}</p>}<button className="bf-primary full" onClick={save}><Check size={17} /> Salvează</button></Modal>;
}

function BudgetBar({ used, total, tone = "green" }: { used: number; total: number; tone?: "green" | "gold" | "coral" }) { const percent = total > 0 ? Math.min(100, Math.max(0, used / total * 100)) : 0; return <div className={`bf-progress ${tone}`} aria-label={`${Math.round(percent)}% utilizat`}><span style={{ width: `${percent}%` }} /></div>; }

function planMath(data: AppData) {
  const plan = data.settings.salaryPlan;
  const sourceIds = plan.sourceIds.length ? plan.sourceIds : data.settings.paymentSources.map((source) => source.id);
  const selected = data.settings.paymentSources.filter((source) => sourceIds.includes(source.id));
  const availableSources = selected.reduce((sum, source) => sum + sourceBalance(data, source.id), 0);
  const periodExpenses = data.transactions.filter((item) => item.kind === "expense" && inPlanPeriod(item.date, plan)).reduce((sum, item) => sum + item.amount, 0);
  const budget = plan.totalLimit || Math.max(0, availableSources);
  const days = plan.nextPayday ? Math.max(1, Math.floor((new Date(`${plan.nextPayday}T12:00:00`).valueOf() - new Date(`${plan.periodStart}T12:00:00`).valueOf()) / 86400000) + 1) : 7;
  const weeks = Math.max(1, Math.ceil(days / 7));
  const weekly = plan.weeklyLimit || budget / weeks;
  const scheduled = pendingRecurringInPlan(data).reduce((sum, item) => sum + item.amount, 0);
  return { plan, sourceIds, selected, availableSources, budget, periodExpenses, scheduled, remaining: budget - periodExpenses - scheduled, days, weeks, weekly };
}

function advisorSignals(data: AppData): AdvisorSignal[] {
  const math = planMath(data);
  const forecast = planForecast(data);
  const signals: AdvisorSignal[] = [];
  const pending = pendingRecurringInPlan(data).sort((a, b) => a.dueDate.localeCompare(b.dueDate));
  if (!math.plan.nextPayday) {
    signals.push({ id: "plan-needed", tone: "watch", eyebrow: "URMĂTORUL PAS", title: "Alege următorul venit", detail: "Planul are nevoie de o dată de salariu pentru a calcula ritmul sigur de cheltuire.", action: "plan", actionLabel: "Configurează planul" });
  } else if (math.remaining < 0) {
    signals.push({ id: "over-plan", tone: "risk", eyebrow: "ATENȚIE", title: `Planul este peste limită cu ${money(Math.abs(math.remaining))}`, detail: `Sunt incluse ${money(math.periodExpenses)} cheltuieli și ${money(math.scheduled)} rezervate până la ${dateText(math.plan.nextPayday)}.`, action: "plan", actionLabel: "Revizuiește planul" });
  } else if (forecast.spentToDate > 0 && forecast.projectedRemaining < 0) {
    signals.push({ id: "pace-risk", tone: "risk", eyebrow: "RITM DE REVIZUIT", title: `La ritmul actual lipsesc ${money(Math.abs(forecast.projectedRemaining))}`, detail: `Cheltuielile sunt în medie ${money(forecast.paceDaily)} pe zi; ritmul sigur este ${money(forecast.safeDaily)} pe zi până la venit.`, action: "plan", actionLabel: "Ajustează planul" });
  } else {
    const daily = math.remaining / Math.max(1, math.days);
    signals.push({ id: "daily-pace", tone: "good", eyebrow: "RITM SIGUR", title: `${money(daily)} pe zi până la venit`, detail: `${money(math.remaining)} rămân după cheltuielile înregistrate și rezervele deja planificate.`, action: "plan", actionLabel: "Vezi calculele" });
  }
  if (pending[0]) {
    signals.push({ id: "next-recurring", tone: "watch", eyebrow: "SCADENȚĂ REZERVATĂ", title: `${pending[0].name} · ${money(pending[0].amount)}`, detail: `Este programată pentru ${dateText(pending[0].dueDate, true)} și este deja exclusă din suma disponibilă.`, action: "recurring", actionLabel: "Deschide scadențele" });
  }
  const allocation = data.settings.salaryPlan.allocations.map((item) => ({ item, spent: allocationSpent(data, item) })).sort((a, b) => (b.spent / Math.max(1, b.item.amount)) - (a.spent / Math.max(1, a.item.amount)))[0];
  if (allocation && allocation.spent >= allocation.item.amount * 0.8) {
    const over = allocation.spent > allocation.item.amount;
    signals.push({ id: `allocation-${allocation.item.id}`, tone: over ? "risk" : "watch", eyebrow: over ? "PLIC DEPĂȘIT" : "APROAPE DE LIMITĂ", title: `${allocation.item.label}: ${money(Math.max(0, allocation.item.amount - allocation.spent))} rămași`, detail: `${money(allocation.spent)} cheltuiți din ${money(allocation.item.amount)} în perioada activă.`, action: "plan", actionLabel: "Vezi plicul" });
  }
  const goal = data.savings.filter((item) => item.target > item.current).sort((a, b) => (b.target - b.current) - (a.target - a.current))[0];
  if (goal && signals.length < 3) signals.push({ id: `goal-${goal.id}`, tone: "good", eyebrow: "OBIECTIV COMUN", title: `${money(goal.target - goal.current)} până la ${goal.name}`, detail: `Progres actual: ${money(goal.current)} din ${money(goal.target)}.`, action: "objectives", actionLabel: "Vezi obiectivul" });
  return signals.slice(0, 3);
}

function HomeView({ data, onAdd, onGo }: { data: AppData; onAdd: () => void; onGo: (view: MainView, more?: MoreView) => void }) {
  const { plan, budget, remaining, days, weekly, periodExpenses, scheduled } = planMath(data); const income = data.transactions.filter((item) => item.kind === "income").reduce((sum, item) => sum + item.amount, 0); const debts = data.debts.reduce((sum, item) => sum + item.monthly, 0); const upcoming = data.debts.filter((item) => item.dueDate).sort((a, b) => String(a.dueDate).localeCompare(String(b.dueDate))).slice(0, 2);
  const overPlan = remaining < 0;
  const signals = advisorSignals(data);
  const openSignal = (action: AdvisorAction) => action === "plan" ? onGo("plan") : action === "objectives" ? onGo("objectives") : action === "journal" ? onGo("journal") : onGo("more", "recurring");
  return <div className="bf-page bf-home"><header className="bf-topline"><div><p className="bf-kicker">ZIUA DE AZI · {dateText(isoToday(), true)}</p><h1>Bună, <em>{data.settings.familyName}.</em></h1><p>O singură întrebare: ce sumă poate fi cheltuită liniștit până la următorul venit?</p></div><button className="bf-primary" onClick={onAdd}><Plus size={18} /> Adaugă</button></header><section className={`bf-safe-card ${overPlan ? "risk" : ""}`}><div><p className="bf-kicker">{overPlan ? "PESTE LIMITA PLANULUI" : "DISPONIBIL ÎN PLAN"}</p><strong>{money(remaining)}</strong><p>{overPlan ? `Planul este depășit cu ${money(Math.abs(remaining))}. Verifică sursele sau limita.` : plan.nextPayday ? `${days} zile până la următorul salariu · limită recomandată ${money(weekly)}/săptămână` : "Alege următorul salariu în Plan"}</p></div><div className="bf-safe-stats"><span><b>{money(budget)}</b> planificat</span><span><b>{money(periodExpenses)}</b> cheltuit</span>{scheduled > 0 && <span><b>{money(scheduled)}</b> de rezervat</span>}<button onClick={() => onGo("plan")}>Deschide planul <ChevronRight size={15} /></button></div></section><section className="bf-family-checkin" aria-labelledby="checkin-title"><div className="bf-checkin-heading"><div><p className="bf-kicker">CHECK-IN DE FAMILIE</p><h2 id="checkin-title">Ce merită decis acum</h2></div><button onClick={() => onGo("more", "assistant")}><Bot size={16} /> Asistent</button></div><div className="bf-checkin-list">{signals.map((signal) => <article key={signal.id} className={signal.tone}><span className="bf-checkin-dot" aria-hidden="true" /><div><p>{signal.eyebrow}</p><b>{signal.title}</b><small>{signal.detail}</small></div><button onClick={() => openSignal(signal.action)}>{signal.actionLabel}<ChevronRight size={15} /></button></article>)}</div></section><div className="bf-quick-grid"><button onClick={onAdd}><WalletCards size={19} /><span>Înregistrează</span><small>venit sau cheltuială</small></button><button onClick={() => onGo("plan")}><CalendarDays size={19} /><span>Planifică</span><small>până la salariu</small></button><button onClick={() => onGo("more", "assistant")}><Bot size={19} /><span>Întreabă</span><small>asistentul local</small></button></div><section className="bf-section"><div className="bf-section-heading"><div><p className="bf-kicker">PULSUL PERIOADEI</p><h2>Unde este atenția acum</h2></div><button onClick={() => onGo("journal")}>Jurnal <ChevronRight size={15} /></button></div><div className="bf-pulse-grid"><article><span className="bf-pulse-icon income"><ArrowDownRight size={16} /></span><p>Venituri</p><strong>{money(income)}</strong></article><article><span className="bf-pulse-icon debt"><BellRing size={16} /></span><p>Rate lunare</p><strong>{money(debts)}</strong></article><article><span className="bf-pulse-icon goal"><PiggyBank size={16} /></span><p>Economii</p><strong>{money(data.savings.reduce((sum, item) => sum + item.current, 0))}</strong></article></div></section>{upcoming.length > 0 && <section className="bf-upcoming"><p className="bf-kicker">URMĂTOARELE OBLIGAȚII</p>{upcoming.map((debt) => <div key={debt.id}><span>{debt.name}<small>{debt.due}</small></span><b>{money(debt.monthly)}</b></div>)}</section>}<section className="bf-section"><div className="bf-section-heading"><div><p className="bf-kicker">ULTIMELE MIȘCĂRI</p><h2>Registrul familiei</h2></div><button onClick={() => onGo("journal")}>Vezi toate <ChevronRight size={15} /></button></div><div className="bf-ledger-mini">{data.transactions.slice(0, 5).map((item) => <div key={item.id}><span className={`bf-tx-icon ${item.kind}`} >{item.kind === "income" ? <ArrowDownRight size={16} /> : <ArrowUpRight size={16} />}</span><span><b>{item.title}</b><small>{dateText(item.date)} · {item.person} · {item.source}</small></span><strong className={item.kind}>{item.kind === "income" ? "+" : "−"}{fmtExact.format(item.amount)}</strong></div>)}{!data.transactions.length && <p className="bf-empty-inline"><b>Prima decizie:</b> înregistrează prima mișcare, apoi planul va arăta ce poate fi cheltuit liniștit.</p>}</div></section></div>;
}

function JournalView({ data, onEdit, onDelete, onAdd }: { data: AppData; onEdit: (item: Transaction) => void; onDelete: (id: string) => void; onAdd: () => void }) {
  const [kind, setKind] = useState<"all" | TransactionKind>("all"); const [member, setMember] = useState("all"); const [source, setSource] = useState("all");
  const list = data.transactions.filter((item) => (kind === "all" || item.kind === kind) && (member === "all" || item.memberId === member) && (source === "all" || item.sourceId === source));
  return <div className="bf-page"><header className="bf-topline compact"><div><p className="bf-kicker">JURNAL DE FAMILIE</p><h1>Fiecare leu, <em>cu context.</em></h1></div><button className="bf-primary" onClick={onAdd}><Plus size={18} /> Adaugă</button></header><section className="bf-filter-sheet"><div className="bf-segment small"><button className={kind === "all" ? "active" : ""} onClick={() => setKind("all")}>Toate</button><button className={kind === "expense" ? "active expense" : ""} onClick={() => setKind("expense")}>Cheltuieli</button><button className={kind === "income" ? "active income" : ""} onClick={() => setKind("income")}>Venituri</button></div><div className="bf-filter-selects"><select value={member} onChange={(event) => setMember(event.target.value)}><option value="all">Toți membrii</option>{data.settings.members.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><select value={source} onChange={(event) => setSource(event.target.value)}><option value="all">Toate sursele</option>{data.settings.paymentSources.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></div></section><section className="bf-journal">{list.map((item) => <article key={item.id}><span className={`bf-tx-icon ${item.kind}`}>{item.kind === "income" ? <ArrowDownRight size={17} /> : <ArrowUpRight size={17} />}</span><div className="bf-journal-name"><b>{item.title}</b><small>{dateText(item.date, true)} · {item.person} · {item.source}</small><span>{item.category}{item.note ? ` · ${item.note}` : ""}</span></div><strong className={item.kind}>{item.kind === "income" ? "+" : "−"}{fmtExact.format(item.amount)}</strong><div className="bf-row-actions"><button aria-label={`Modifică ${item.title}`} onClick={() => onEdit(item)}>Modifică</button><button aria-label={`Șterge ${item.title}`} onClick={() => window.confirm(`Ștergi mișcarea „${item.title}”?`) && onDelete(item.id)}><Trash2 size={16} /></button></div></article>)}{!list.length && <div className="bf-empty-state"><ReceiptText size={24} /><h2>Nu sunt mișcări în acest filtru</h2><p>Schimbă filtrul sau adaugă prima intrare.</p><button className="bf-primary" onClick={onAdd}><Plus size={16} /> Adaugă mișcare</button></div>}</section></div>;
}

function PlanView({ data, onChange }: { data: AppData; onChange: (data: AppData) => void }) {
  const plan = data.settings.salaryPlan; const [allocationMode, setAllocationMode] = useState<"member" | "category">("member"); const [target, setTarget] = useState(data.settings.members[0]?.id || ""); const [amount, setAmount] = useState("");
  const maths = planMath(data); const updatePlan = (patch: Partial<typeof plan>) => onChange({ ...data, settings: { ...data.settings, salaryPlan: { ...plan, ...patch } } });
  const toggleSource = (id: string) => { const all = data.settings.paymentSources.map((item) => item.id); const current = plan.sourceIds.length ? plan.sourceIds : all; const next = current.includes(id) ? current.filter((value) => value !== id) : [...current, id]; updatePlan({ sourceIds: next.length === all.length ? [] : next }); };
  const addAllocation = () => { const numeric = parseRomanianAmount(amount); if (numeric <= 0) return; const member = data.settings.members.find((item) => item.id === target); const allocation: BudgetAllocation = { id: newId("allocation"), label: allocationMode === "member" ? member?.name || "Membru" : target, amount: numeric, memberId: allocationMode === "member" ? target : undefined, category: allocationMode === "category" ? target : undefined }; updatePlan({ allocations: [...plan.allocations, allocation] }); setAmount(""); };
  const periods = Array.from({ length: maths.weeks }, (_, index) => { const start = new Date(`${plan.periodStart}T12:00:00`); start.setDate(start.getDate() + index * 7); const end = new Date(Math.min(start.valueOf() + 6 * 86400000, plan.nextPayday ? new Date(`${plan.nextPayday}T12:00:00`).valueOf() : start.valueOf() + 6 * 86400000)); const startIso = start.toISOString().slice(0, 10); const endIso = end.toISOString().slice(0, 10); const spent = data.transactions.filter((item) => item.kind === "expense" && item.date >= startIso && item.date <= endIso).reduce((sum, item) => sum + item.amount, 0); const allowance = index === maths.weeks - 1 ? Math.max(0, maths.budget - maths.weekly * index) : maths.weekly; return { start, end, spent, allowance }; });
  const targets = allocationMode === "member" ? data.settings.members.map((item) => ({ id: item.id, name: item.name })) : [...expenseCategories, ...data.settings.customCategories].map((item) => ({ id: item, name: item }));
  return <div className="bf-page"><header className="bf-topline compact"><div><p className="bf-kicker">PLAN PÂNĂ LA URMĂTORUL VENIT</p><h1>Fă loc banilor <em>înainte de cheltuială.</em></h1></div></header><section className="bf-plan-hero"><div><p>Disponibil în această perioadă</p><strong>{money(Math.max(0, maths.remaining))}</strong><span>{maths.days} zile · {maths.weeks} săptămâni · {money(maths.weekly)} / săptămână</span></div><div className="bf-plan-hero-data"><span>Buget <b>{money(maths.budget)}</b></span><span>Cheltuit <b>{money(maths.periodExpenses)}</b></span><span>Surse <b>{money(maths.availableSources)}</b></span></div></section><section className="bf-period-card"><div className="bf-section-heading"><div><p className="bf-kicker">1. PERIOADA</p><h2>Când intră următorii bani?</h2></div><CalendarDays size={19} /></div><div className="bf-form-grid"><Field label="Începe la"><input type="date" value={plan.periodStart} onChange={(event) => updatePlan({ periodStart: event.target.value })} /></Field><Field label="Următorul salariu / venit"><input type="date" min={plan.periodStart} value={plan.nextPayday} onChange={(event) => updatePlan({ nextPayday: event.target.value })} /></Field></div></section><section className="bf-period-card"><div className="bf-section-heading"><div><p className="bf-kicker">2. BANII DE FOLOSIT</p><h2>Alege sursele și limita</h2></div><WalletCards size={19} /></div><div className="bf-source-list">{data.settings.paymentSources.map((source) => { const active = !plan.sourceIds.length || plan.sourceIds.includes(source.id); return <label key={source.id} className={active ? "active" : ""}><input type="checkbox" checked={active} onChange={() => toggleSource(source.id)} /><span><b>{source.name}</b><small>{data.settings.members.find((member) => member.id === source.memberId)?.name || "Comun"}</small></span><strong>{money(sourceBalance(data, source.id))}</strong></label>; })}</div><div className="bf-form-grid"><Field label="Limită totală pentru perioadă" hint="Dacă rămâne goală, se folosește soldul surselor selectate."><input inputMode="decimal" value={plan.totalLimit ? String(plan.totalLimit) : ""} onChange={(event) => updatePlan({ totalLimit: Math.max(0, parseRomanianAmount(event.target.value)) })} placeholder={maths.availableSources ? money(maths.availableSources) : "ex. 600"} /></Field><Field label="Limită săptămânală" hint="Dacă rămâne goală, împărțim automat."><input inputMode="decimal" value={plan.weeklyLimit ? String(plan.weeklyLimit) : ""} onChange={(event) => updatePlan({ weeklyLimit: Math.max(0, parseRomanianAmount(event.target.value)) })} placeholder={money(maths.budget / maths.weeks)} /></Field></div></section><section className="bf-section"><div className="bf-section-heading"><div><p className="bf-kicker">3. RITMUL SĂPTĂMÂNII</p><h2>Bugetat, cheltuit, rămas</h2></div></div><div className="bf-week-list">{periods.map((week, index) => <article key={index}><div><b>Săpt. {index + 1}</b><small>{dateText(week.start.toISOString().slice(0, 10))} – {dateText(week.end.toISOString().slice(0, 10))}</small></div><strong>{money(Math.max(0, week.allowance - week.spent))}</strong><BudgetBar used={week.spent} total={week.allowance} tone={week.spent > week.allowance ? "coral" : "gold"} /><span>{money(week.spent)} cheltuit din {money(week.allowance)}</span></article>)}</div></section><section className="bf-section"><div className="bf-section-heading"><div><p className="bf-kicker">4. PLICURI DE BUGET</p><h2>Repartizează pentru oameni și categorii</h2></div></div><div className="bf-allocation-form"><select value={allocationMode} onChange={(event) => { const mode = event.target.value as typeof allocationMode; setAllocationMode(mode); setTarget(mode === "member" ? data.settings.members[0]?.id || "" : expenseCategories[0]); }}><option value="member">Membru</option><option value="category">Categorie</option></select><select value={target} onChange={(event) => setTarget(event.target.value)}>{targets.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" placeholder="lei" /><button className="bf-primary" onClick={addAllocation}><Plus size={17} /> Alocă</button></div><div className="bf-allocation-list">{plan.allocations.map((allocation) => { const spent = allocationSpent(data, allocation); return <article key={allocation.id}><div><b>{allocation.label}</b><small>{allocation.memberId ? "Buget personal" : "Buget de categorie"}</small></div><div><strong>{money(Math.max(0, allocation.amount - spent))}</strong><span>rămas din {money(allocation.amount)}</span></div><BudgetBar used={spent} total={allocation.amount} tone={spent > allocation.amount ? "coral" : "green"} /><button aria-label={`Șterge ${allocation.label}`} onClick={() => updatePlan({ allocations: plan.allocations.filter((item) => item.id !== allocation.id) })}><Trash2 size={16} /></button></article>; })}{!plan.allocations.length && <p className="bf-empty-inline">Alocă, de exemplu, 300 lei pentru fiecare membru sau 150 lei pentru Taxi.</p>}</div></section></div>;
}

function ObjectivesView({ data, onDebt, onSaving, onDeleteDebt, onDeleteSaving, openDebt, openSaving }: { data: AppData; onDebt: (item: Debt) => void; onSaving: (item: SavingsGoal) => void; onDeleteDebt: (id: string) => void; onDeleteSaving: (id: string) => void; openDebt: () => void; openSaving: () => void }) { return <div className="bf-page"><header className="bf-topline compact"><div><p className="bf-kicker">OBLIGAȚII ȘI OBIECTIVE</p><h1>Ce protejăm și <em>ce construim.</em></h1></div></header><section className="bf-objective-switch"><button className="bf-primary" onClick={openDebt}><Plus size={17} /> Datorie</button><button className="bf-secondary" onClick={openSaving}><Plus size={17} /> Economie</button></section><div className="bf-objective-columns"><section><div className="bf-section-heading"><div><p className="bf-kicker">DATORII</p><h2>Rate și împrumuturi</h2></div><span>{money(data.debts.reduce((sum, item) => sum + item.remaining, 0))}</span></div>{data.debts.map((debt) => <article className="bf-objective-card debt" key={debt.id}><div><b>{debt.name}</b><small>{debt.due}</small></div><strong>{money(debt.remaining)}</strong><p>Rată: {money(debt.monthly)} / lună</p><button aria-label={`Șterge ${debt.name}`} onClick={() => onDeleteDebt(debt.id)}><Trash2 size={16} /></button></article>)}{!data.debts.length && <div className="bf-empty-state slim"><BellRing size={23} /><h2>Nicio datorie</h2><p>Adaugă ratele pe care vrei să le incluzi în plan.</p></div>}</section><section><div className="bf-section-heading"><div><p className="bf-kicker">ECONOMII</p><h2>Ținte comune</h2></div><span>{money(data.savings.reduce((sum, item) => sum + item.current, 0))}</span></div>{data.savings.map((saving) => <article className="bf-objective-card saving" key={saving.id}><div><b>{saving.name}</b><small>{saving.due}</small></div><strong>{money(saving.current)}</strong><BudgetBar used={saving.current} total={saving.target} tone="gold" /><p>{money(Math.max(0, saving.target - saving.current))} până la {money(saving.target)}</p><button aria-label={`Șterge ${saving.name}`} onClick={() => onDeleteSaving(saving.id)}><Trash2 size={16} /></button></article>)}{!data.savings.length && <div className="bf-empty-state slim"><PiggyBank size={23} /><h2>Niciun obiectiv</h2><p>Începe cu un fond de siguranță sau o țintă importantă.</p></div>}</section></div></div>; }

function ReceiptForm({ data, onSave, onClose }: { data: AppData; onSave: (item: Receipt) => void; onClose: () => void }) {
  const [vendor, setVendor] = useState(""); const [amount, setAmount] = useState(""); const [date, setDate] = useState(isoToday()); const [sourceId, setSourceId] = useState(data.settings.paymentSources[0]?.id || ""); const [memberId, setMemberId] = useState(data.settings.members[0]?.id || ""); const [note, setNote] = useState(""); const [images, setImages] = useState<string[]>([]); const [lines, setLines] = useState<Array<{ id: string; category: string; amount: string; label: string }>>([{ id: newId("receipt-line"), category: "Alimente", amount: "", label: "" }]); const [ocrText, setOcrText] = useState(""); const [ocrSummary, setOcrSummary] = useState(""); const [busy, setBusy] = useState(false); const [progress, setProgress] = useState(0); const [error, setError] = useState("");
  const categories = [...expenseCategories, ...data.settings.customCategories];
  const lineTotal = lines.reduce((sum, line) => sum + parseRomanianAmount(line.amount), 0);
  const pick = async (files?: FileList | null) => {
    const selected = files ? Array.from(files) : [];
    if (!selected.length) return;
    if (images.length + selected.length > 2) return setError("Un bon poate avea maximum două fotografii. Elimină una înainte de a adăuga alta.");
    try { setBusy(true); setError(""); const compressed = await Promise.all(selected.map(compressReceiptImage)); setImages((current) => [...current, ...compressed]); } catch (reason) { setError(reason instanceof Error ? reason.message : "Poza bonului nu a putut fi procesată."); } finally { setBusy(false); }
  };
  const scan = async () => {
    try { setBusy(true); setError(""); setOcrSummary(""); setProgress(0); const result = await readReceiptLocally(images, setProgress); setOcrText(result.text); if (result.amount) setAmount(String(result.amount)); if (result.date) setDate(result.date); if (result.text && !note.trim()) setNote(result.text.slice(0, 1400)); if (result.items.length) { const suggestedLines = result.items.map((item) => ({ id: newId("receipt-line"), category: categories.includes(item.category) ? item.category : "Alimente", amount: String(item.amount), label: item.label })); setLines(suggestedLines); const detectedTotal = result.items.reduce((sum, item) => sum + item.amount, 0); setOcrSummary(`Am propus ${result.items.length} produs${result.items.length === 1 ? "" : "e"} cu prețuri individuale (${fmtExact.format(detectedTotal)}). Verifică produsele, categoriile și totalul înainte de salvare.`); } else { setOcrSummary("Am citit textul și totalul, dar nu am identificat sigur linii de produse. Completează repartizarea manual."); } } catch (reason) { setError(reason instanceof Error ? reason.message : "Textul de pe bon nu a putut fi citit."); } finally { setBusy(false); setProgress(0); }
  };
  const updateLine = (id: string, patch: Partial<(typeof lines)[number]>) => setLines((current) => current.map((line) => line.id === id ? { ...line, ...patch } : line));
  const save = () => {
    const numeric = parseRomanianAmount(amount);
    const normalizedLines: ReceiptLine[] = lines.map((line) => ({ id: line.id, category: line.category, amount: parseRomanianAmount(line.amount), label: line.label.trim() || undefined })).filter((line) => line.amount > 0);
    if (normalizedLines.length === 0 && numeric > 0 && lines.length === 1) normalizedLines.push({ id: lines[0].id, category: lines[0].category, amount: numeric, label: lines[0].label.trim() || undefined });
    const splitTotal = normalizedLines.reduce((sum, line) => sum + line.amount, 0);
    if (!vendor.trim() || numeric <= 0 || !sourceId || !memberId) return setError("Completează magazinul, totalul, membrul și sursa.");
    if (!normalizedLines.length || Math.abs(numeric - splitTotal) > 0.01) return setError(`Repartizarea este ${fmtExact.format(splitTotal)}, dar totalul bonului este ${fmtExact.format(numeric)}. Corectează liniile înainte de salvare.`);
    onSave({ id: newId("receipt"), vendor: vendor.trim(), amount: numeric, date, category: normalizedLines[0].category, lines: normalizedLines, sourceId, memberId, note: note.trim() || undefined, imageData: images[0], imageData2: images[1], ocrText: ocrText || undefined }); onClose();
  };
  return <Modal title="Adaugă bon" onClose={onClose}><div className="bf-receipt-intro"><p className="bf-kicker">BON CU REPARTIZARE</p><p>Poți fotografia un bon lung în două părți; imaginile se comprimă local înainte de salvare.</p></div><div className="bf-form-grid"><Field label="Magazin"><input autoFocus value={vendor} onChange={(event) => setVendor(event.target.value)} placeholder="ex. Lidl" /></Field><Field label="Total (lei)"><input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" placeholder="0,00" /></Field><Field label="Data"><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></Field><Field label="Membru"><select value={memberId} onChange={(event) => setMemberId(event.target.value)}>{data.settings.members.map((member) => <option key={member.id} value={member.id}>{member.name}</option>)}</select></Field><Field label="Plătit din"><select value={sourceId} onChange={(event) => setSourceId(event.target.value)}>{data.settings.paymentSources.map((source) => <option key={source.id} value={source.id}>{source.name}</option>)}</select></Field></div><section className="bf-receipt-images"><div><p className="bf-kicker">FOTOGRAFIILE BONULUI</p><strong>{images.length}/2 imagini</strong></div><label className="bf-upload-control"><Camera size={18} /> {busy && !progress ? "Comprimăm…" : "Adaugă poze"}<input type="file" accept="image/*" capture="environment" multiple disabled={busy || images.length >= 2} onChange={(event) => { void pick(event.target.files); event.currentTarget.value = ""; }} /></label>{images.length > 0 && <button className="bf-ocr-button" disabled={busy} onClick={() => void scan()}><Bot size={17} /> {busy && progress ? `Citim ${progress}%` : "Citește produsele și prețurile local"}</button>}<div className="bf-receipt-preview-grid">{images.map((image, index) => <figure key={image}><img src={image} alt={`Previzualizare bon partea ${index + 1}`} /><button aria-label={`Elimină fotografia ${index + 1}`} onClick={() => setImages((current) => current.filter((_, imageIndex) => imageIndex !== index))}><X size={15} /></button></figure>)}</div>{ocrSummary && <p className="bf-ocr-info" role="status"><Bot size={16} /> {ocrSummary}</p>}</section><section className="bf-receipt-split"><div className="bf-split-heading"><div><p className="bf-kicker">PRODUSE ȘI CATEGORII</p><h3>{fmtExact.format(lineTotal)} din {amount ? fmtExact.format(parseRomanianAmount(amount)) : "0,00 RON"}</h3></div><button className="bf-secondary" onClick={() => setLines((current) => [...current, { id: newId("receipt-line"), category: "Alimente", amount: "", label: "" }])}><Plus size={16} /> Produs</button></div>{lines.map((line) => <div className="bf-split-line" key={line.id}><select aria-label="Categorie bon" value={line.category} onChange={(event) => updateLine(line.id, { category: event.target.value })}>{categories.map((item) => <option key={item}>{item}</option>)}</select><input aria-label="Preț produs" value={line.amount} onChange={(event) => updateLine(line.id, { amount: event.target.value })} inputMode="decimal" placeholder="lei" /><input aria-label="Produs" value={line.label} onChange={(event) => updateLine(line.id, { label: event.target.value })} placeholder="ex. fructe" />{lines.length > 1 && <button aria-label="Elimină produsul" onClick={() => setLines((current) => current.filter((entry) => entry.id !== line.id))}><Trash2 size={16} /></button>}</div>)}<small>OCR-ul propune linii editabile. Fiecare linie devine o cheltuială reală, iar totalul liniilor trebuie să fie egal cu totalul bonului.</small></section>{ocrText && <Field label="Text citit local (verifică înainte de salvare)"><textarea value={note} onChange={(event) => setNote(event.target.value)} /></Field>}{!ocrText && <Field label="Produse / notiță"><textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="ex. apă, fructe, detergent" /></Field>}{error && <p className="bf-form-error" role="alert">{error}</p>}<button className="bf-primary full" disabled={busy} onClick={save}><Check size={17} /> Salvează bonul și cheltuielile</button></Modal>;
}

function AdvisorStudio({ data }: { data: AppData }) {
  const math = planMath(data); const forecast = planForecast(data); const [question, setQuestion] = useState(""); const [scenario, setScenario] = useState("");
  const responseFor = (raw: string) => {
    const query = raw.toLowerCase(); const top = Object.entries(data.transactions.filter((item) => item.kind === "expense" && inPlanPeriod(item.date, math.plan)).reduce<Record<string, number>>((all, item) => ({ ...all, [item.category]: (all[item.category] || 0) + item.amount }), {})).sort((a, b) => b[1] - a[1])[0];
    if (query.includes("dator") || query.includes("rat")) return data.debts.length ? `Ratele lunare însumează ${money(data.debts.reduce((sum, item) => sum + item.monthly, 0))}. Cea mai mare obligație este ${[...data.debts].sort((a, b) => b.remaining - a.remaining)[0].name}.` : "Nu ai înregistrat datorii. Adaugă o rată dacă vrei să fie rezervată în plan.";
    if (query.includes("progno") || query.includes("ritm") || query.includes("ajung")) return math.plan.nextPayday ? `Cheltuielile înregistrate au un ritm de ${money(forecast.paceDaily)} pe zi. Dacă ritmul se păstrează, până la ${dateText(math.plan.nextPayday)} ar rămâne ${money(forecast.projectedRemaining)} după rezerve. Ritmul sigur, din planul curent, este ${money(forecast.safeDaily)} pe zi.` : "Alege data următorului venit în Plan pentru a calcula o proiecție până la salariu.";
    if (query.includes("chelt") || query.includes("mult") || query.includes("categorie")) return top ? `În perioada activă, ${top[0]} este categoria principală: ${money(top[1])}. Răspunsul folosește mișcările dintre ${dateText(math.plan.periodStart)} și ${math.plan.nextPayday ? dateText(math.plan.nextPayday) : "sfârșitul perioadei"}.` : "Nu există încă cheltuieli în perioada activă.";
    if (query.includes("plan") || query.includes("limit") || query.includes("salariu")) return `Planul are ${money(math.budget)} disponibili, ${money(math.periodExpenses)} cheltuiți și ${money(Math.max(0, math.remaining))} rămași până la următorul venit. Limita curentă este ${money(math.weekly)} pe săptămână.`;
    return `În perioada activă sunt ${math.days} zile, cu ${money(Math.max(0, math.remaining))} disponibili. Întreabă despre ritm, plan, cheltuieli, datorii sau obiective.`;
  };
  const [answer, setAnswer] = useState(() => responseFor("")); const scenarioAmount = parseRomanianAmount(scenario); const scenarioRemaining = forecast.projectedRemaining - scenarioAmount;
  const ask = (value = question) => { setQuestion(value); setAnswer(responseFor(value)); };
  const runScenario = () => { if (scenarioAmount <= 0) return setAnswer("Introdu o sumă mai mare decât zero pentru a testa scenariul. Această simulare nu adaugă o cheltuială în registru."); setAnswer(`Dacă adaugi o cheltuială de ${money(scenarioAmount)} acum, proiecția până la venit devine ${money(scenarioRemaining)}. ${scenarioRemaining < 0 ? `Ar lipsi ${money(Math.abs(scenarioRemaining))}; ajustează planul sau amână o cheltuială flexibilă.` : `Rămâne o marjă estimată de ${money(scenarioRemaining)}.`}`); };
  return <div className="bf-advisor-studio"><section className="bf-advisor-hero"><div className="bf-assistant-symbol"><Bot size={22} /></div><p className="bf-kicker">ASISTENT DE DECIZIE LOCAL</p><h2>Ce se întâmplă dacă păstrați ritmul?</h2><p>Folosește planul, registrul și scadențele de pe acest telefon. Nu trimite date financiare către un serviciu extern.</p><div className="bf-advisor-metrics"><span><small>Ritm actual</small><b>{money(forecast.paceDaily)}/zi</b></span><span><small>Ritm sigur</small><b>{money(forecast.safeDaily)}/zi</b></span><span><small>La venit</small><b className={forecast.projectedRemaining < 0 ? "risk" : ""}>{money(forecast.projectedRemaining)}</b></span></div></section><section className="bf-scenario-card"><div><p className="bf-kicker">SCENARIU RAPID</p><h3>Testează o cheltuială înainte de plată</h3><p>Nu schimbă datele până când alegi să înregistrezi separat mișcarea.</p></div><div><input value={scenario} onChange={(event) => setScenario(event.target.value)} inputMode="decimal" placeholder="ex. 120" aria-label="Sumă pentru scenariu" /><button className="bf-primary" onClick={runScenario}>Testează</button></div></section><section className="bf-advisor-answer" aria-live="polite"><p className="bf-kicker">RĂSPUNS EXPLICABIL</p><p>{answer}</p></section><div className="bf-advisor-prompts"><button onClick={() => ask("Care este prognoza până la salariu?")}>Prognoza până la venit</button><button onClick={() => ask("Pe ce cheltuim cel mai mult?")}>Categoria principală</button><button onClick={() => ask("Care sunt ratele și datoriile?")}>Rate și datorii</button></div><div className="bf-advisor-question"><input value={question} onChange={(event) => setQuestion(event.target.value)} onKeyDown={(event) => event.key === "Enter" && ask()} placeholder="ex. Ajungem la salariu cu ritmul actual?" /><button aria-label="Analizează" onClick={() => ask()}><Send size={18} /></button></div><small className="bf-advisor-note">Asistent explicabil, nu consultanță financiară, fiscală sau de investiții. O funcție AI externă ar necesita acord explicit și o infrastructură separată, securizată.</small></div>;
}

function MoreView({ tab, setTab, data, onChange, onAddReceipt, onDeleteReceipt, onOpenDebt, onOpenSaving }: { tab: MoreView; setTab: (value: MoreView) => void; data: AppData; onChange: (value: AppData) => void; onAddReceipt: () => void; onDeleteReceipt: (id: string) => void; onOpenDebt: () => void; onOpenSaving: () => void }) {
  const tabs: { id: MoreView; label: string; icon: typeof SlidersHorizontal }[] = [{ id: "overview", label: "Instrumente", icon: MoreHorizontal }, { id: "debts", label: "Datorii", icon: BellRing }, { id: "savings", label: "Economii", icon: PiggyBank }, { id: "receipts", label: "Bonuri", icon: ReceiptText }, { id: "recurring", label: "Scadențe", icon: CalendarDays }, { id: "reports", label: "Statistici", icon: LayoutDashboard }, { id: "assistant", label: "Asistent", icon: Bot }, { id: "settings", label: "Setări", icon: Settings }, { id: "sync", label: "Sync", icon: Cloud }, { id: "guide", label: "Ghid", icon: BookOpen }];
  const setSettings = (patch: Partial<AppData["settings"]>) => onChange({ ...data, settings: { ...data.settings, ...patch } });
  const content = () => {
    if (tab === "overview") return <div className="bf-more-grid"><button onClick={onOpenDebt}><BellRing size={20} /><b>Datorii</b><span>{data.debts.length} active</span></button><button onClick={onOpenSaving}><PiggyBank size={20} /><b>Economii</b><span>{data.savings.length} obiective</span></button><button onClick={onAddReceipt}><Camera size={20} /><b>Bonuri</b><span>{data.receipts.length} salvate</span></button><button onClick={() => setTab("recurring")}><CalendarClock size={20} /><b>Scadențe</b><span>{data.recurring.length} programate</span></button><button onClick={() => setTab("assistant")}><Bot size={20} /><b>Asistent</b><span>explică datele</span></button><button onClick={() => setTab("settings")}><Settings size={20} /><b>Setări familie</b><span>membri și surse</span></button><button onClick={() => setTab("sync")}><Cloud size={20} /><b>Sincronizare</b><span>familie conectată</span></button><button onClick={() => setTab("guide")}><BookOpen size={20} /><b>Manual</b><span>configurare și utilizare</span></button></div>;
    if (tab === "debts") return <div className="bf-more-list">{data.debts.map((debt) => <article key={debt.id}><span><b>{debt.name}</b><small>{debt.due}</small></span><strong>{money(debt.remaining)}</strong><em>{money(debt.monthly)}/lună</em></article>)}{!data.debts.length && <div className="bf-empty-state slim"><BellRing size={23} /><h2>Nicio datorie</h2><button className="bf-primary" onClick={onOpenDebt}><Plus size={16} /> Adaugă datorie</button></div>}</div>;
    if (tab === "savings") return <div className="bf-more-list">{data.savings.map((saving) => <article key={saving.id}><span><b>{saving.name}</b><small>{saving.due}</small></span><strong>{money(saving.current)}</strong><BudgetBar used={saving.current} total={saving.target} tone="gold" /></article>)}{!data.savings.length && <div className="bf-empty-state slim"><PiggyBank size={23} /><h2>Niciun obiectiv</h2><button className="bf-primary" onClick={onOpenSaving}><Plus size={16} /> Creează obiectiv</button></div>}</div>;
    if (tab === "receipts") return <div><button className="bf-primary bf-inline-add" onClick={onAddReceipt}><Camera size={17} /> Adaugă bon</button><div className="bf-receipt-list">{data.receipts.map((receipt) => <article key={receipt.id}>{receipt.imageData ? <img src={receipt.imageData} alt={`Bon ${receipt.vendor}`} /> : <span className="bf-receipt-icon"><ReceiptText size={21} /></span>}<div><b>{receipt.vendor}</b><small>{dateText(receipt.date)} · {receipt.lines?.length || 1} categorie{(receipt.lines?.length || 1) === 1 ? "" : "i"}</small><p>{receipt.lines?.map((line) => `${line.category}: ${money(line.amount)}`).join(" · ") || receipt.note || "Fără detalii"}</p>{receipt.imageData2 && <small>Bon în două fotografii</small>}</div><strong>{money(receipt.amount)}</strong><button aria-label={`Șterge bonul ${receipt.vendor}`} onClick={() => onDeleteReceipt(receipt.id)}><Trash2 size={16} /></button></article>)}{!data.receipts.length && <div className="bf-empty-state slim"><ReceiptText size={23} /><h2>Niciun bon</h2><p>Un bon poate avea două poze și mai multe categorii; fiecare categorie creează o cheltuială legată de același bon.</p></div>}</div></div>;
    if (tab === "recurring") return <RecurringPanel data={data} onChange={onChange} />;
    if (tab === "reports") return <ReportsPanel data={data} />;
    if (tab === "assistant") return <AdvisorStudio data={data} />;
    if (tab === "settings") return <SettingsPanel data={data} onChange={onChange} onReset={() => window.confirm("Ștergi toate datele locale de pe acest dispozitiv?") && onChange(createEmptyAppData())} />;
    if (tab === "guide") return <FamilyGuide />;
    return <SyncPanel data={data} onChange={onChange} />;
  };
  return <div className="bf-page"><header className="bf-topline compact"><div><p className="bf-kicker">MAI MULT</p><h1>Instrumentele <em>familiei.</em></h1></div></header><div className="bf-more-tabs">{tabs.map((item) => { const Icon = item.icon; return <button key={item.id} className={tab === item.id ? "active" : ""} onClick={() => setTab(item.id)}><Icon size={16} /> {item.label}</button>; })}</div>{content()}</div>;
}

function SettingsPanel({ data, onChange, onReset }: { data: AppData; onChange: (value: AppData) => void; onReset: () => void }) {
  const [member, setMember] = useState(""); const [source, setSource] = useState(""); const [kind, setKind] = useState<PaymentKind>("card"); const [owner, setOwner] = useState(data.settings.members[0]?.id || ""); const [category, setCategory] = useState("");
  const settings = data.settings; const change = (patch: Partial<typeof settings>) => onChange({ ...data, settings: { ...settings, ...patch } });
  const addMember = () => { if (!member.trim()) return; if (settings.members.some((item) => item.name.toLowerCase() === member.trim().toLowerCase())) return; change({ members: [...settings.members, { id: newId("member"), name: member.trim() }] }); setMember(""); };
  const addSource = () => { if (!source.trim()) return; change({ paymentSources: [...settings.paymentSources, { id: newId("source"), name: source.trim(), kind, memberId: kind === "transfer" ? undefined : owner, openingBalance: 0 }] }); setSource(""); };
  return <div className="bf-settings"><section><p className="bf-kicker">FAMILIE</p><Field label="Numele familiei"><input value={settings.familyName} onChange={(event) => change({ familyName: event.target.value })} /></Field><Field label="Numele tău"><input value={settings.memberName} onChange={(event) => change({ memberName: event.target.value })} /></Field><Field label="Cod local de familie" hint="Codul ajută la verificarea exportului manual."><input value={settings.familyCode} onChange={(event) => change({ familyCode: event.target.value.toUpperCase() })} /><button className="bf-link-button" onClick={() => change({ familyCode: createFamilyCode() })}><RotateCcw size={14} /> Cod nou</button></Field></section><section><p className="bf-kicker">MEMBRI</p><div className="bf-chip-list">{settings.members.map((item) => <span key={item.id}>{item.name}{settings.members.length > 1 && <button onClick={() => change({ members: settings.members.filter((memberItem) => memberItem.id !== item.id) })}><X size={14} /></button>}</span>)}</div><div className="bf-mini-form"><input value={member} onChange={(event) => setMember(event.target.value)} placeholder="ex. Soția" /><button onClick={addMember}>Adaugă</button></div></section><section><p className="bf-kicker">SURSE ȘI SOLD INITIAL</p>{settings.paymentSources.map((item) => <div className="bf-source-edit" key={item.id}><span><b>{item.name}</b><small>{sourceKindName[item.kind]} · {settings.members.find((memberItem) => memberItem.id === item.memberId)?.name || "Comun"}</small></span><label><small>Sold inițial</small><input inputMode="decimal" value={String(item.openingBalance)} onChange={(event) => change({ paymentSources: settings.paymentSources.map((sourceItem) => sourceItem.id === item.id ? { ...sourceItem, openingBalance: Math.max(0, parseRomanianAmount(event.target.value)) } : sourceItem) })} /></label><strong>{money(sourceBalance(data, item.id))}</strong></div>)}<div className="bf-source-builder"><input value={source} onChange={(event) => setSource(event.target.value)} placeholder="ex. Card soție" /><select value={kind} onChange={(event) => setKind(event.target.value as PaymentKind)}>{Object.entries(sourceKindName).map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select><select value={owner} disabled={kind === "transfer"} onChange={(event) => setOwner(event.target.value)}>{settings.members.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><button onClick={addSource}>Adaugă</button></div></section><section><p className="bf-kicker">CATEGORII PROPRII</p><div className="bf-chip-list">{settings.customCategories.map((item) => <span key={item}>{item}<button onClick={() => change({ customCategories: settings.customCategories.filter((categoryItem) => categoryItem !== item) })}><X size={14} /></button></span>)}</div><div className="bf-mini-form"><input value={category} onChange={(event) => setCategory(event.target.value)} placeholder="ex. Taxi" /><button onClick={() => { if (category.trim() && !settings.customCategories.includes(category.trim())) { change({ customCategories: [...settings.customCategories, category.trim()] }); setCategory(""); } }}>Adaugă</button></div></section><section className="bf-danger"><p className="bf-kicker">RESETARE</p><h2>Începe curat pe acest dispozitiv</h2><p>Șterge numai datele locale. O copie sincronizată sau exportată nu este afectată.</p><button onClick={onReset}><Trash2 size={16} /> Resetează datele locale</button></section></div>;
}

function SyncPanel({ data, onChange }: { data: AppData; onChange: (value: AppData) => void }) {
  const [token, setToken] = useState(""); const [password, setPassword] = useState(""); const [notice, setNotice] = useState(""); const [busy, setBusy] = useState(false); const [connected, setConnected] = useState(false); const [lastSync, setLastSync] = useState(""); const shaRef = useRef<string | undefined>(undefined); const dataRef = useRef(data); dataRef.current = data;
  const owner = "Balty1991"; const repo = "buget-familie-date"; const path = "family-sync.enc.json";
  const check = () => { if (!token.trim()) throw new Error("Introdu un token GitHub limitat la repo-ul privat de date."); if (password.length < 12) throw new Error("Parola de criptare trebuie să aibă cel puțin 12 caractere."); };
  const portable = (value: AppData) => ({ ...value, receipts: value.receipts.map(({ imageData: _one, imageData2: _two, ...rest }) => rest) });
  const retainLocalReceiptImages = (value: AppData): AppData => ({ ...value, receipts: value.receipts.map((receipt) => { const local = dataRef.current.receipts.find((item) => item.id === receipt.id); return { ...receipt, imageData: local?.imageData, imageData2: local?.imageData2 }; }) });
  const syncNow = async (announce = true): Promise<boolean> => {
    check(); setBusy(true);
    try {
      const remote = await getRemotePackage({ token, owner, repo, path });
      const remoteData = remote ? normalizeAppData(await decryptFamilyData(remote.envelope, password)) : createEmptyAppData();
      const merged = retainLocalReceiptImages(remote ? mergeFamilyData(dataRef.current, remoteData) : dataRef.current);
      if (remote && JSON.stringify(portable(merged)) === JSON.stringify(portable(remoteData))) {
        shaRef.current = remote.sha; onChange(merged); setLastSync(new Date().toISOString()); if (announce) setNotice("Familia era deja actualizată. Nu a fost creat un commit nou."); return true;
      }
      const envelope = await encryptFamilyData(portable(merged), password);
      const nextSha = await saveRemotePackage({ token, owner, repo, path, envelope, sha: remote?.sha });
      shaRef.current = nextSha; onChange(merged); setLastSync(new Date().toISOString()); if (announce) setNotice("Familia este actualizată. Modificările au fost reunite și criptate."); return true;
    } catch (error) { setNotice(error instanceof Error ? error.message : "Nu s-a putut actualiza familia."); return false; } finally { setBusy(false); }
  };
  const connect = async () => { if (!token.trim() || password.length < 12) return setNotice("Introdu tokenul repo-ului privat și o parolă de cel puțin 12 caractere."); if (await syncNow(false)) { setConnected(true); setNotice("Sesiunea familiei este activă. Verificăm actualizări la aproximativ 30 de secunde cât aplicația rămâne deschisă."); } };
  const pull = async () => { try { check(); setBusy(true); const remote = await getRemotePackage({ token, owner, repo, path }); if (!remote) return setNotice("Nu există încă o copie în repo-ul privat."); const restored = normalizeAppData(await decryptFamilyData(remote.envelope, password)); onChange(retainLocalReceiptImages(mergeFamilyData(dataRef.current, restored))); shaRef.current = remote.sha; setLastSync(new Date().toISOString()); setNotice("Actualizările familiei au fost reunite local, fără a șterge intrările acestei sesiuni."); } catch (error) { setNotice(error instanceof Error ? error.message : "Nu s-a putut descărca copia."); } finally { setBusy(false); } };
  useEffect(() => { if (!connected) return; const interval = window.setInterval(() => { void syncNow(false); }, 30_000); return () => window.clearInterval(interval); }, [connected, token, password]);
  return <div className="bf-sync"><div className="bf-sync-hero"><Users size={25} /><p className="bf-kicker">FAMILIE CONECTATĂ</p><h2>{connected ? "Sesiunea familiei este activă." : "Sincronizare criptată între telefoane."}</h2><p>În repo-ul privat ajunge doar un pachet AES-GCM. Pozele bonurilor și parola rămân pe telefon.</p></div><section className="bf-sync-session"><p className="bf-kicker">{connected ? "CONECTAT" : "CONECTEAZĂ FAMILIA"}</p>{connected ? <><p><b>Actualizare prudentă la aproximativ 30 secunde</b><br />Sesiunea funcționează cât aplicația este deschisă. Tokenul rămâne doar în memorie.</p><div className="bf-sync-actions"><button className="bf-secondary" disabled={busy} onClick={() => void pull()}><Download size={16} /> Verifică acum</button><button className="bf-primary" disabled={busy} onClick={() => void syncNow()}><Cloud size={16} /> Sincronizează acum</button></div><button className="bf-link-button" onClick={() => { setConnected(false); setToken(""); setPassword(""); setNotice("Sesiunea a fost închisă pe acest telefon."); }}>Închide sesiunea acestui telefon</button></> : <><Field label="Token GitHub limitat"><input type="password" value={token} onChange={(event) => setToken(event.target.value)} placeholder="github_pat_..." autoComplete="off" /></Field><Field label="Parola de criptare a familiei"><input type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="minimum 12 caractere" autoComplete="new-password" /></Field><p className="bf-helper">Pe fiecare telefon se folosește un token fine-grained separat, cu <b>Contents: Read and write</b> doar pentru repo-ul privat <b>{repo}</b>. Tokenul și parola nu se salvează.</p><button className="bf-primary full" disabled={busy} onClick={() => void connect()}><Users size={17} /> Conectează acest telefon</button></>}</section>{lastSync && <p className="bf-helper">Ultima actualizare: {new Intl.DateTimeFormat("ro-RO", { hour: "2-digit", minute: "2-digit", second: "2-digit" }).format(new Date(lastSync))}</p>}{notice && <p className="bf-notice" role="status"><Check size={15} /> {notice}</p>}</div>;
}

function FamilyGuide() { return <div className="bf-guide"><section className="bf-guide-hero"><BookOpen size={25} /><p className="bf-kicker">MANUAL RAPID</p><h2>Familia, pe aceeași pagină.</h2><p>Pași simpli pentru configurare, conectarea telefoanelor și folosirea zilnică a aplicației.</p></section><section><p className="bf-kicker">1. PORNEȘTE FAMILIA</p><h3>Configurează membrii și banii reali</h3><p>În <b>Setări familie</b>, adaugă membrii, cardurile/cash-ul și soldurile inițiale. Apoi creează planul până la următorul salariu.</p></section><section><p className="bf-kicker">2. CONECTEAZĂ TELEFOANELE</p><h3>Folosește repo-ul privat, nu repo-ul aplicației</h3><p>Administratorul creează tokenuri fine-grained distincte cu <b>Contents: Read and write</b> numai pentru <b>buget-familie-date</b>. Pe fiecare telefon, deschide <b>Mai mult → Sincronizare</b>, introdu tokenul propriu și aceeași parolă de familie, apoi apasă „Conectează acest telefon”.</p></section><section><p className="bf-kicker">3. LUCREAZĂ ZILNIC</p><h3>Înregistrează, verifică, decide</h3><p>Adaugă mișcările la momentul plății. Pentru cumpărături mixte, un bon poate avea două poze și mai multe categorii. Verifică zilnic cardul „Check-in de familie” și confirmă scadențele când sunt plătite.</p></section><section><p className="bf-kicker">4. PROTEJEAZĂ DATELE</p><h3>Nu trimite parole sau tokenuri</h3><p>Tokenul și parola nu sunt salvate de aplicație. Nu le pune în conversații, bonuri sau capturi de ecran. Dacă un telefon se pierde, revocă tokenul acelui telefon în GitHub și creează unul nou.</p></section></div>; }

export default function Home() {
  const [data, setData] = useState<AppData>(() => { try { const raw = window.localStorage.getItem(STORE_KEY) || window.localStorage.getItem(LEGACY_KEY); return raw ? normalizeAppData(JSON.parse(raw)) : createEmptyAppData(); } catch { return createEmptyAppData(); } });
  const [view, setView] = useState<MainView>("home"); const [more, setMore] = useState<MoreView>("overview"); const [modal, setModal] = useState<"transaction" | "receipt" | "debt" | "saving" | null>(null); const [editTx, setEditTx] = useState<Transaction>(); const [dark, setDark] = useState(() => window.localStorage.getItem("buget-familie:theme") === "dark");
  useEffect(() => { window.localStorage.setItem(STORE_KEY, JSON.stringify(data)); }, [data]); useEffect(() => { document.documentElement.classList.toggle("dark", dark); window.localStorage.setItem("buget-familie:theme", dark ? "dark" : "light"); }, [dark]); useEffect(() => { window.scrollTo({ top: 0, behavior: "instant" as ScrollBehavior }); }, [view, more]);
  const update = (fn: (current: AppData) => AppData) => setData((current) => fn(current));
  const saveTx = (item: Transaction) => update((current) => { const stamped = { ...item, updatedAt: new Date().toISOString() }; return { ...current, transactions: current.transactions.some((entry) => entry.id === item.id) ? current.transactions.map((entry) => entry.id === item.id ? stamped : entry) : [stamped, ...current.transactions] }; });
  const saveDebt = (item: Debt | SavingsGoal) => update((current) => { const stamped = { ...item, updatedAt: new Date().toISOString() } as Debt; return { ...current, debts: current.debts.some((entry) => entry.id === item.id) ? current.debts.map((entry) => entry.id === item.id ? stamped : entry) : [...current.debts, stamped] }; });
  const saveSaving = (item: Debt | SavingsGoal) => update((current) => { const stamped = { ...item, updatedAt: new Date().toISOString() } as SavingsGoal; return { ...current, savings: current.savings.some((entry) => entry.id === item.id) ? current.savings.map((entry) => entry.id === item.id ? stamped : entry) : [...current.savings, stamped] }; });
  const saveReceipt = (item: Receipt) => update((current) => { const member = current.settings.members.find((entry) => entry.id === item.memberId) || current.settings.members[0]; const source = current.settings.paymentSources.find((entry) => entry.id === item.sourceId) || current.settings.paymentSources[0]; const lines = item.lines?.length ? item.lines : [{ id: "whole", category: item.category, amount: item.amount }]; const transactionIds = lines.map((line) => `receipt-tx-${item.id}-${line.id}`); const receipt = { ...item, linkedTransactionId: transactionIds[0], linkedTransactionIds: transactionIds }; const transactions: Transaction[] = lines.map((line, index) => ({ id: transactionIds[index], receiptId: item.id, title: `Bon — ${item.vendor}${line.label ? ` · ${line.label}` : ""}`, amount: line.amount, kind: "expense", category: line.category, sourceId: source?.id, source: source?.name || "Bon", memberId: member?.id, person: member?.name || current.settings.memberName, date: item.date, note: item.note, createdAt: new Date().toISOString() })); const formerIds = current.receipts.find((entry) => entry.id === item.id)?.linkedTransactionIds || [item.linkedTransactionId, `receipt-tx-${item.id}`].filter((value): value is string => Boolean(value)); return { ...current, receipts: [receipt, ...current.receipts.filter((entry) => entry.id !== item.id)], transactions: [...transactions, ...current.transactions.filter((entry) => !formerIds.includes(entry.id) && entry.receiptId !== item.id)] }; });
  const deleteReceipt = (id: string) => update((current) => { const receipt = current.receipts.find((item) => item.id === id); const linked = receipt?.linkedTransactionIds || [receipt?.linkedTransactionId, `receipt-tx-${id}`].filter((value): value is string => Boolean(value)); const now = new Date().toISOString(); return { ...current, receipts: current.receipts.filter((item) => item.id !== id), transactions: current.transactions.filter((item) => !linked.includes(item.id) && item.receiptId !== id), deleted: [...current.deleted, { entity: "receipts" as const, id, deletedAt: now }, ...linked.map((transactionId) => ({ entity: "transactions" as const, id: transactionId, deletedAt: now }))].slice(-500) }; });
  const openTx = (item?: Transaction) => { setEditTx(item); setModal("transaction"); };
  const nav = [{ id: "home" as MainView, label: "Acasă", icon: LayoutDashboard }, { id: "journal" as MainView, label: "Jurnal", icon: WalletCards }, { id: "plan" as MainView, label: "Plan", icon: Goal }, { id: "objectives" as MainView, label: "Obiective", icon: PiggyBank }, { id: "more" as MainView, label: "Mai mult", icon: MoreHorizontal }];
  const current = () => { if (view === "journal") return <JournalView data={data} onAdd={() => openTx()} onEdit={openTx} onDelete={(id) => update((currentData) => ({ ...currentData, transactions: currentData.transactions.filter((item) => item.id !== id), receipts: currentData.receipts.filter((receipt) => receipt.linkedTransactionId !== id), deleted: [...currentData.deleted, { entity: "transactions" as const, id, deletedAt: new Date().toISOString() }].slice(-500) }))} />; if (view === "plan") return <PlanView data={data} onChange={setData} />; if (view === "objectives") return <ObjectivesView data={data} onDebt={(item) => saveDebt(item)} onSaving={(item) => saveSaving(item)} onDeleteDebt={(id) => update((currentData) => ({ ...currentData, debts: currentData.debts.filter((item) => item.id !== id), deleted: [...currentData.deleted, { entity: "debts" as const, id, deletedAt: new Date().toISOString() }].slice(-500) }))} onDeleteSaving={(id) => update((currentData) => ({ ...currentData, savings: currentData.savings.filter((item) => item.id !== id), deleted: [...currentData.deleted, { entity: "savings" as const, id, deletedAt: new Date().toISOString() }].slice(-500) }))} openDebt={() => setModal("debt")} openSaving={() => setModal("saving")} />; if (view === "more") return <MoreView tab={more} setTab={setMore} data={data} onChange={setData} onAddReceipt={() => setModal("receipt")} onDeleteReceipt={deleteReceipt} onOpenDebt={() => setModal("debt")} onOpenSaving={() => setModal("saving")} />; return <HomeView data={data} onAdd={() => openTx()} onGo={(next, tab) => { setView(next); if (tab) setMore(tab); }} />; };
  return <div className="bf-app"><header className="bf-appbar"><button className="bf-brand" onClick={() => setView("home")}><span className="bf-brand-mark" aria-hidden="true"><i /></span><b>Buget <i>Familie</i></b></button><nav aria-label="Navigație principală">{nav.map((item) => { const Icon = item.icon; return <button key={item.id} className={view === item.id ? "active" : ""} onClick={() => setView(item.id)}><Icon size={17} /><span>{item.label}</span></button>; })}</nav><button className="bf-theme" aria-label="Schimbă tema" onClick={() => setDark((value) => !value)}>{dark ? <Sun size={18} /> : <Moon size={18} />}</button></header><main>{current()}</main><nav className="bf-mobile-nav" aria-label="Navigație mobilă">{nav.map((item) => { const Icon = item.icon; return <button key={item.id} className={view === item.id ? "active" : ""} onClick={() => setView(item.id)}><Icon size={20} /><span>{item.label}</span></button>; })}</nav>{modal === "transaction" && <TransactionForm data={data} initial={editTx} onSave={saveTx} onClose={() => { setModal(null); setEditTx(undefined); }} />}{modal === "receipt" && <ReceiptForm data={data} onSave={saveReceipt} onClose={() => setModal(null)} />}{modal === "debt" && <GoalForm type="debt" onSave={saveDebt} onClose={() => setModal(null)} />}{modal === "saving" && <GoalForm type="saving" onSave={saveSaving} onClose={() => setModal(null)} />}</div>;
}
